"""
Flask Todo API — flat-file storage with JWT authentication.

A single-file Flask app with clean structure: models, routes, error handling.
All data is stored in a JSON flat file (no databases).

Endpoints:
  POST /auth/register   -> create a user
  POST /auth/login      -> issue a JWT
  /tasks/*              -> require a valid JWT (owner-scoped)
"""

import functools
import json
import os
import threading
from datetime import datetime, timedelta

import jwt
from flask import Flask, g, jsonify, request
from werkzeug.security import check_password_hash, generate_password_hash

app = Flask(__name__)
app.config["SECRET_KEY"] = os.environ.get("SECRET_KEY", "dev-secret-key")

DATA_FILE = os.environ.get("DATA_FILE", "tasks.json")
TOKEN_TTL = timedelta(hours=12)
_lock = threading.Lock()


def _read() -> dict:
    with open(DATA_FILE) as f:
        return json.load(f)


def _write(store: dict) -> None:
    with open(DATA_FILE, "w") as f:
        json.dump(store, f, indent=2)


def init_store() -> None:
    with _lock:
        if not os.path.exists(DATA_FILE):
            _write({"tasks": [], "next_id": 1, "users": [], "next_user_id": 1})
        else:
            store = _read()
            if _migrate(store):
                _write(store)


def _migrate(store: dict) -> bool:
    """Bring old stores up to date without destroying existing data."""
    changed = False
    if "users" not in store:
        store["users"] = []
        changed = True
    if "next_user_id" not in store:
        store["next_user_id"] = 1
        changed = True

    ownerless = [
        t for t in store.get("tasks", [])
        if t.get("owner_id") is None
    ]
    if ownerless:
        legacy = next(
            (u for u in store["users"] if u["username"] == "legacy"), None
        )
        if legacy is None:
            legacy = {
                "id": store["next_user_id"],
                "username": "legacy",
                "password_hash": generate_password_hash("legacy"),
            }
            store["next_user_id"] += 1
            store["users"].append(legacy)
        for task in ownerless:
            task["owner_id"] = legacy["id"]
        changed = True
    return changed


# ── Models: Users ──────────────────────────────────────────────

def create_user(username: str, password: str) -> dict:
    with _lock:
        store = _read()
        if any(u["username"] == username for u in store["users"]):
            return None
        user = {
            "id": store["next_user_id"],
            "username": username,
            "password_hash": generate_password_hash(password),
        }
        store["next_user_id"] += 1
        store["users"].append(user)
        _write(store)
        return user


def get_user_by_username(username: str) -> dict | None:
    store = _read()
    for user in store["users"]:
        if user["username"] == username:
            return user
    return None


def get_user(user_id: int) -> dict | None:
    store = _read()
    for user in store["users"]:
        if user["id"] == user_id:
            return user
    return None


def verify_user(username: str, password: str) -> dict | None:
    user = get_user_by_username(username)
    if user is None or not check_password_hash(user["password_hash"], password):
        return None
    return user


# ── Models: Tasks ──────────────────────────────────────────────

def create_task(title: str, owner_id: int) -> dict:
    with _lock:
        store = _read()
        task = {
            "id": store["next_id"],
            "title": title,
            "status": "pending",
            "owner_id": owner_id,
            "created_at": datetime.utcnow().isoformat(),
        }
        store["tasks"].append(task)
        store["next_id"] += 1
        _write(store)
        return task


def get_tasks(owner_id: int) -> list:
    store = _read()
    mine = [t for t in store["tasks"] if t.get("owner_id") == owner_id]
    return sorted(mine, key=lambda t: t["created_at"], reverse=True)


def get_task(task_id: int, owner_id: int) -> dict | None:
    store = _read()
    for task in store["tasks"]:
        if task["id"] == task_id and task.get("owner_id") == owner_id:
            return task
    return None


def update_task(
    task_id: int,
    owner_id: int,
    title: str | None = None,
    status: str | None = None,
) -> dict | None:
    with _lock:
        store = _read()
        for task in store["tasks"]:
            if task["id"] == task_id and task.get("owner_id") == owner_id:
                if title is not None:
                    task["title"] = title
                if status is not None:
                    task["status"] = status
                _write(store)
                return task
    return None


# ── Auth helpers ───────────────────────────────────────────────

def token_for(user: dict) -> str:
    payload = {
        "sub": user["id"],
        "username": user["username"],
        "exp": datetime.utcnow() + TOKEN_TTL,
    }
    return jwt.encode(payload, app.config["SECRET_KEY"], algorithm="HS256")


def auth_required(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        header = request.headers.get("Authorization", "")
        token = header[7:] if header.startswith("Bearer ") else None
        if not token:
            return jsonify({"error": "missing or invalid token"}), 401
        try:
            payload = jwt.decode(
                token, app.config["SECRET_KEY"], algorithms=["HS256"]
            )
        except jwt.PyJWTError:
            return jsonify({"error": "missing or invalid token"}), 401
        user = get_user(payload.get("sub"))
        if user is None:
            return jsonify({"error": "missing or invalid token"}), 401
        g.current_user = user
        return func(*args, **kwargs)

    return wrapper


# ── Routes: Auth ───────────────────────────────────────────────

@app.route("/auth/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")
    if not isinstance(username, str) or not username.strip():
        return jsonify({"error": "username is required"}), 400
    if not isinstance(password, str) or not password:
        return jsonify({"error": "password is required"}), 400
    user = create_user(username.strip(), password)
    if user is None:
        return jsonify({"error": "username already exists"}), 409
    return jsonify({"id": user["id"], "username": user["username"], "token": token_for(user)}), 201


@app.route("/auth/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")
    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({"error": "username and password are required"}), 400
    user = verify_user(username, password)
    if user is None:
        return jsonify({"error": "invalid credentials"}), 401
    return jsonify({"token": token_for(user)})


# ── Routes: Tasks ──────────────────────────────────────────────

@app.route("/tasks", methods=["GET"])
@auth_required
def list_tasks():
    return jsonify(get_tasks(g.current_user["id"]))


@app.route("/tasks", methods=["POST"])
@auth_required
def add_task():
    data = request.get_json(silent=True) or {}
    title = data.get("title")
    if not isinstance(title, str) or not title.strip():
        return jsonify({"error": "title is required"}), 400
    task = create_task(title.strip(), g.current_user["id"])
    return jsonify(task), 201


@app.route("/tasks/<int:task_id>", methods=["GET"])
@auth_required
def show_task(task_id: int):
    task = get_task(task_id, g.current_user["id"])
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.route("/tasks/<int:task_id>", methods=["PUT"])
@auth_required
def edit_task(task_id: int):
    data = request.get_json(silent=True) or {}
    task = update_task(
        task_id,
        g.current_user["id"],
        title=data.get("title"),
        status=data.get("status"),
    )
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


if __name__ == "__main__":
    init_store()
    app.run(debug=True)

import json
import os

import pytest

import app as app_module


@pytest.fixture()
def client(tmp_path):
    app_module.DATA_FILE = str(tmp_path / "tasks.json")
    app_module.init_store()
    app_module.app.config["TESTING"] = True
    with app_module.app.test_client() as c:
        yield c


@pytest.fixture()
def alice(client):
    resp = client.post(
        "/auth/register", json={"username": "alice", "password": "secret"}
    )
    assert resp.status_code == 201
    token = resp.get_json()["token"]
    return {"username": "alice", "token": token}


@pytest.fixture()
def auth(alice):
    return {"Authorization": f"Bearer {alice['token']}"}


@pytest.fixture()
def bob(client):
    resp = client.post(
        "/auth/register", json={"username": "bob", "password": "bobpass"}
    )
    assert resp.status_code == 201
    return {"username": "bob", "token": resp.get_json()["token"]}


@pytest.fixture()
def bob_auth(bob):
    return {"Authorization": f"Bearer {bob['token']}"}


# ── Auth: register ─────────────────────────────────────────────

def test_register_success(client):
    resp = client.post(
        "/auth/register", json={"username": "carol", "password": "pw"}
    )
    assert resp.status_code == 201
    data = resp.get_json()
    assert data["username"] == "carol"
    assert "token" in data


def test_register_missing_fields(client):
    assert client.post("/auth/register", json={}).status_code == 400
    assert client.post("/auth/register", json={"username": "x"}).status_code == 400
    assert client.post("/auth/register", json={"password": "x"}).status_code == 400


def test_register_duplicate_username(client):
    client.post("/auth/register", json={"username": "dave", "password": "pw"})
    resp = client.post("/auth/register", json={"username": "dave", "password": "pw"})
    assert resp.status_code == 409
    assert "error" in resp.get_json()


def test_register_hashes_password(client):
    client.post("/auth/register", json={"username": "eve", "password": "pw"})
    with open(app_module.DATA_FILE) as f:
        store = json.load(f)
    user = next(u for u in store["users"] if u["username"] == "eve")
    assert "password_hash" in user
    assert user["password_hash"] != "pw"


# ── Auth: login ────────────────────────────────────────────────

def test_login_success(client):
    client.post("/auth/register", json={"username": "frank", "password": "pw"})
    resp = client.post(
        "/auth/login", json={"username": "frank", "password": "pw"}
    )
    assert resp.status_code == 200
    assert "token" in resp.get_json()


def test_login_wrong_password(client):
    client.post("/auth/register", json={"username": "frank", "password": "pw"})
    resp = client.post(
        "/auth/login", json={"username": "frank", "password": "nope"}
    )
    assert resp.status_code == 401


def test_login_unknown_user(client):
    resp = client.post(
        "/auth/login", json={"username": "ghost", "password": "pw"}
    )
    assert resp.status_code == 401


# ── Auth: protecting /tasks ────────────────────────────────────

def test_tasks_require_token(client):
    assert client.get("/tasks").status_code == 401
    assert client.post("/tasks", json={"title": "x"}).status_code == 401
    assert client.get("/tasks/1").status_code == 401
    assert client.put("/tasks/1", json={"title": "x"}).status_code == 401


def test_tasks_reject_invalid_token(client):
    headers = {"Authorization": "Bearer not-a-real-token"}
    assert client.get("/tasks", headers=headers).status_code == 401
    assert client.post("/tasks", json={"title": "x"}, headers=headers).status_code == 401


def test_tasks_reject_garbage_header(client):
    headers = {"Authorization": "Basic abc"}
    assert client.get("/tasks", headers=headers).status_code == 401


# ── Tasks: CRUD (authed) ───────────────────────────────────────

def test_create_task(client, auth):
    resp = client.post("/tasks", json={"title": "Buy milk"}, headers=auth)
    assert resp.status_code == 201
    data = resp.get_json()
    assert data["title"] == "Buy milk"
    assert data["status"] == "pending"
    assert data["id"] == 1


def test_create_task_missing_title(client, auth):
    resp = client.post("/tasks", json={}, headers=auth)
    assert resp.status_code == 400
    assert "error" in resp.get_json()


def test_create_task_blank_title(client, auth):
    resp = client.post("/tasks", json={"title": "   "}, headers=auth)
    assert resp.status_code == 400


def test_list_tasks_ordered_desc(client, auth):
    client.post("/tasks", json={"title": "first"}, headers=auth)
    client.post("/tasks", json={"title": "second"}, headers=auth)
    resp = client.get("/tasks", headers=auth)
    assert resp.status_code == 200
    titles = [t["title"] for t in resp.get_json()]
    assert titles == ["second", "first"]


def test_get_task(client, auth):
    created = client.post("/tasks", json={"title": "alpha"}, headers=auth).get_json()
    resp = client.get(f"/tasks/{created['id']}", headers=auth)
    assert resp.status_code == 200
    assert resp.get_json()["title"] == "alpha"


def test_get_task_not_found(client, auth):
    resp = client.get("/tasks/999", headers=auth)
    assert resp.status_code == 404
    assert "error" in resp.get_json()


def test_update_task(client, auth):
    created = client.post("/tasks", json={"title": "alpha"}, headers=auth).get_json()
    resp = client.put(
        f"/tasks/{created['id']}", json={"title": "beta", "status": "done"}, headers=auth
    )
    assert resp.status_code == 200
    data = resp.get_json()
    assert data["title"] == "beta"
    assert data["status"] == "done"


def test_update_task_partial(client, auth):
    created = client.post("/tasks", json={"title": "alpha"}, headers=auth).get_json()
    resp = client.put(
        f"/tasks/{created['id']}", json={"status": "in_progress"}, headers=auth
    )
    data = resp.get_json()
    assert data["status"] == "in_progress"
    assert data["title"] == "alpha"


def test_update_task_not_found(client, auth):
    resp = client.put("/tasks/999", json={"title": "x"}, headers=auth)
    assert resp.status_code == 404
    assert "error" in resp.get_json()


def test_persists_to_flat_file(client, auth):
    client.post("/tasks", json={"title": "persisted"}, headers=auth)
    with open(app_module.DATA_FILE) as f:
        store = json.load(f)
    assert any(t["title"] == "persisted" for t in store["tasks"])


# ── Ownership isolation ────────────────────────────────────────

def test_users_only_see_own_tasks(client, auth, bob_auth):
    client.post("/tasks", json={"title": "alice task"}, headers=auth)
    client.post("/tasks", json={"title": "bob task"}, headers=bob_auth)

    alice_titles = [t["title"] for t in client.get("/tasks", headers=auth).get_json()]
    bob_titles = [t["title"] for t in client.get("/tasks", headers=bob_auth).get_json()]

    assert alice_titles == ["alice task"]
    assert bob_titles == ["bob task"]


def test_cannot_read_others_task(client, auth, bob_auth):
    created = client.post("/tasks", json={"title": "private"}, headers=auth).get_json()
    resp = client.get(f"/tasks/{created['id']}", headers=bob_auth)
    assert resp.status_code == 404


def test_cannot_update_others_task(client, auth, bob_auth):
    created = client.post("/tasks", json={"title": "private"}, headers=auth).get_json()
    resp = client.put(
        f"/tasks/{created['id']}", json={"title": "hacked"}, headers=bob_auth
    )
    assert resp.status_code == 404


# ── Migration ──────────────────────────────────────────────────

def test_migration_assigns_legacy_tasks(tmp_path):
    store = {
        "tasks": [
            {
                "id": 1,
                "title": "old task",
                "status": "pending",
                "created_at": "2020-01-01T00:00:00",
            }
        ],
        "next_id": 2,
    }
    data_file = str(tmp_path / "old.json")
    with open(data_file, "w") as f:
        json.dump(store, f)

    app_module.DATA_FILE = data_file
    app_module.init_store()

    with open(data_file) as f:
        migrated = json.load(f)
    assert migrated["tasks"][0]["owner_id"] is not None
    assert "users" in migrated
    assert any(u["username"] == "legacy" for u in migrated["users"])
    assert migrated["tasks"][0]["title"] == "old task"

